"""Generates sim/tb/ulpi/tb_usb2_ulpi_axim.sv from sim/tb/tb_usb2_utmi_axim.sv (R-276): the DUT is the ULPI wrapper and the PHY side is
the ULPI BFM (sim/tb/ulpi/ulpi_phy_bfm.sv) that presents "virtual UTMI+" to the unchanged operations, monitors and checkers of
the harness. Deterministic; run from the sim folder:  python scripts/gen_ulpi_tb.py   (add --check to compare only)."""
import os
import re
import sys

import sys as _sys
_sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import vpaths as P  # noqa: E402
SIM = P.V
SRC = os.path.join(P.TB, 'tb_usb2_utmi_axim.sv')
DST = os.path.join(P.TB, 'tb_usb2_ulpi_axim.sv')

s = open(SRC).read()
s = s.replace('module tb_usb2_utmi_axim;', 'module tb_usb2_ulpi_axim;')
s = s.replace('// Generic harness for the wrapper m_usb2_top_utmi_axim', '// GENERATED by scripts/gen_ulpi_tb.py from tb_usb2_utmi_axim.sv. Generic harness for the wrapper m_usb2_top_ulpi_axim (through ulpi_phy_bfm)')
# the transmit-ready of the harness is produced by the BFM (NXT), not by the harness
s = s.replace('logic [15:0] utmi_dataout; logic utmi_txvalid, utmi_txvalidh, utmi_txready = 1;', 'logic [15:0] utmi_dataout; logic utmi_txvalid, utmi_txvalidh = 0, utmi_txready;')
s = re.sub(r"    utmi_txready <= \(txready_low == 0\).*\n", "", s)
a = s.index('  m_usb2_top_utmi_axim #(')
b = s.index('.o_axim_rready(rready));', a) + len('.o_axim_rready(rready));')
inst = s[a:b]
keep = [ln for ln in inst.split('\n') if ln.startswith('    .') and ('axim' in ln or 'apb' in ln)]
axi_apb = '\n'.join(ln for ln in keep)
new = '''  logic ulpi_dir, ulpi_nxt, ulpi_stp, ulpi_oe; logic [7:0] ulpi_d_to_link, ulpi_d_from_link, v_dataout_w;
  int n_regw, n_regr, n_abort; bit abort_req = 0; int abort_after = 0; int n_ulpi_chk, n_ulpi_viol, ulpi_viol_id, n_viol_seen = 0;
  always @(posedge clk_phy) if (n_ulpi_viol != n_viol_seen) begin n_viol_seen = n_ulpi_viol; a_fail("a_ulpi_bus", $sformatf("ULPI bus rule %0d violated", ulpi_viol_id)); end
  assign utmi_dataout = {8'h00, v_dataout_w};
  m_usb2_top_ulpi_axim #(.PARA_USB2_ROLE(ROLE), .PARA_USB2_NUM_EP(NUM_EP), .PARA_USB2_NUM_HC(NUM_HC),
    .PARA_USB2_AXI_DATA_W(AXI_DATA_W), .PARA_USB2_FIFO_DEPTH(FIFO_DEPTH), .PARA_USB2_SG_EN(SG_EN), .PARA_USB2_LPM_EN(LPM_EN),
    .PARA_USB2_SPLIT_EN(SPLIT_EN), .PARA_USB2_TSCALE(TSCALE), .PARA_USB2_PIPE_PHY_IN(PIPE), .PARA_USB2_PIPE_RX(PIPE),
    .PARA_USB2_PIPE_CRC(PIPE), .PARA_USB2_PIPE_MODE(PIPE), .PARA_USB2_PIPE_XREG(PIPE), .PARA_USB2_RAM_1P(PIPE)) dut (
    .i_clk_phy(clk_phy), .i_clk_bus(clk_bus), .i_rst_n_phy(rst_dut), .i_rst_n_bus(rst_dut), .o_phy_rst_n(phy_rst_n),
    .i_protect_en(protect_en), .i_slverr_en(slverr_en), .i_ovrcur_n(ovrcur_n), .o_vbus_pwr_en(vbus_pwr_en),
    .i_dft_test_en(1'b0), .i_dft_scan_en(1'b0), .o_int_usb(int_usb),
    .i_ulpi_dir(ulpi_dir), .i_ulpi_nxt(ulpi_nxt), .o_ulpi_stp(ulpi_stp), .i_ulpi_data(ulpi_d_to_link), .o_ulpi_data(ulpi_d_from_link),
    .o_ulpi_data_oe(ulpi_oe),
''' + axi_apb + '''
  ulpi_phy_bfm bfm (.clk(clk_phy), .rst_n(rst_n), .dir(ulpi_dir), .nxt(ulpi_nxt), .stp(ulpi_stp), .data_from_link(ulpi_d_from_link),
    .data_to_link(ulpi_d_to_link), .v_rxactive(utmi_rxactive), .v_rxvalid(utmi_rxvalid), .v_rxerror(utmi_rxerror),
    .v_datain(utmi_datain[7:0]), .v_linestate(utmi_linestate), .v_vbusvalid(vbusvalid), .v_hostdisc(hostdisc), .v_iddig(iddig),
    .v_txvalid(utmi_txvalid), .v_dataout(v_dataout_w), .v_txready(utmi_txready), .v_opmode(opmode), .v_xcvrsel(xcvrsel),
    .v_termsel(termsel), .v_suspend_n(suspend_n), .v_dppd(dppd), .v_dmpd(dmpd), .v_drvvbus(drvvbus),
    .nxt_low_pct(txready_low), .link_oe(ulpi_oe), .n_chk(n_ulpi_chk), .n_viol(n_ulpi_viol), .viol_id(ulpi_viol_id), .abort_req(abort_req), .abort_after(abort_after), .n_regw(n_regw), .n_regr(n_regr), .n_abort(n_abort));'''
s = s[:a] + new + s[b:]
# extra operations of the ULPI harness: abort pulse and the register counters
s = s.replace('        "WD": begin', '        "AB": begin abort_after = rdi(); abort_req = 1; repeat (2) @(posedge clk_phy); abort_req = 0; end\n        "XR": begin a = rdi(); d = rdi(); chk((a < 0 || n_regw >= a) && (d < 0 || n_regr >= d), $sformatf("line %0d: PHY register accesses write %0d (>= %0d) read %0d (>= %0d)", line_no, n_regw, a, n_regr, d)); end\n        "WD": begin', 1)
s = s.replace('$display("ACTIVITY a_utmi_tx=%0d', '$display("ULPI_ACTIVITY a_ulpi_bus_cycles=%0d violations=%0d", n_ulpi_chk, n_ulpi_viol); $display("ACTIVITY a_utmi_tx=%0d', 1)
# optional debug probe of the adapter state (read only), enabled with +ulpiprobe
PROBE = ('  initial if ($test$plusargs("ulpiprobe")) forever begin @(posedge clk_phy); if (rst_n && $time < 30000000) '
         '$display("PROBE %0t fc_want=%02h fc_wr=%02h pend=%b linkidle=%b txv=%b st=%0d", $time, '
         'dut.u_core.gen_ulpi.u_phyif.w_fc_want, dut.u_core.gen_ulpi.u_phyif.reg_fc_wr, dut.u_core.gen_ulpi.u_phyif.w_mode_pend, '
         'dut.u_core.gen_ulpi.u_phyif.i_link_idle, dut.u_core.gen_ulpi.u_phyif.i_tx_valid, '
         'dut.u_core.gen_ulpi.u_phyif.reg_fsm_ulpi_current_state); end' + chr(10))
s = s.replace('  ulpi_phy_bfm bfm (', PROBE + '  ulpi_phy_bfm bfm (', 1)
out = s
if '--check' in sys.argv:
    same = os.path.exists(DST) and open(DST).read() == out
    print('SAME' if same else 'DIFF')
    sys.exit(0 if same else 1)
os.makedirs(os.path.dirname(DST), exist_ok=True)
open(DST, 'w', newline='\n').write(out)
print('wrote', DST)
